python3 -c 'import sys,json,cmath,math,pathlib;P=pathlib.Path("Zeta_TM_OneLiner.sh").read_bytes();E=lambda b:int.from_bytes(b"\1"+b,"big");D=lambda n:n.to_bytes((n.bit_length()+7)//8,"big")[1:];C=(1/12,-1/720,1/30240);exec("def u(z):\n w=(math.isqrt(8*z+1)-1)//2;t=w*(w+1)//2;y=z-t;return w-y,y\ndef cw(k):\n a=b=1\n for x in bin(k)[3:]:\n  if x==\"0\":b+=a\n  else:a+=b\n return a,b\ndef r(n):\n if n==0:return(0,1)\n a,b=cw((n+1)//2);return(a,b)if n%2 else(-a,b)\ndef q(n):\n a,b=u(n);return r(a),r(b)\ndef z(s,N=64):\n v=sum(k**(-s)for k in range(1,N))+N**(1-s)/(s-1)+.5*N**(-s);p=1\n for j,c in enumerate(C,1):\n  p=s if j==1 else p*(s+2*j-3)*(s+2*j-2);v+=c*p*N**(-s-2*j+1)\n return v\ndef f(i):\n A,B=q(i);x=complex(A[0]/A[1],B[0]/B[1]);X=[list(A),list(B)]\n if A==(1,1)and B==(0,1):Y={\"k\":\"pole\",\"r\":1,\"l\":0}\n elif B==(0,1)and A[1]==1 and A[0]<0 and A[0]%2==0:Y={\"k\":\"zero\",\"v\":0}\n else:\n  a=z(x);b=z(x,128);Y={\"k\":\"num\",\"v\":[b.real,b.imag],\"d\":abs(b-a)}\n return{\"n\":i,\"X\":X,\"Y\":Y}\n");a=sys.argv[1:];S=int(a[0])if a else 0;N=int(a[1])if len(a)>1 else 8;e=E(P);print(json.dumps({"mode":"xy-quine","self":hex(e),"recovered":D(e)==P,"cycle":[f(i)for i in range(S,S+N)],"dense_Qi":True,"closure_C":True,"full_C_pointwise":False,"immediate_exhaustive":False,"quine_preserved":True,"numerical_zero":False,"open":True,"final":False},separators=(",",":")))'